"""CRUD endpoints for expenses."""

from typing import Annotated

from fastapi import APIRouter, Depends, HTTPException, Query, Response, status
from sqlalchemy import select
from sqlalchemy.orm import Session

from app.db import get_session
from app.models import Expense
from app.schemas import ExpenseCreate, ExpenseRead, ExpenseUpdate

router = APIRouter(prefix="/expenses", tags=["expenses"])
SessionDep = Annotated[Session, Depends(get_session)]


def _get_or_404(session: Session, expense_id: int) -> Expense:
    expense = session.get(Expense, expense_id)
    if expense is None:
        raise HTTPException(status.HTTP_404_NOT_FOUND, detail="Expense not found")
    return expense


@router.get("", response_model=list[ExpenseRead])
def list_expenses(
    session: SessionDep,
    limit: Annotated[int, Query(ge=1, le=200)] = 50,
    offset: Annotated[int, Query(ge=0)] = 0,
) -> list[Expense]:
    query = select(Expense).order_by(Expense.id)
    return list(session.scalars(query.offset(offset).limit(limit)))


@router.post("", response_model=ExpenseRead, status_code=status.HTTP_201_CREATED)
def create_expense(payload: ExpenseCreate, session: SessionDep) -> Expense:
    expense = Expense(**payload.model_dump())
    session.add(expense)
    session.commit()
    session.refresh(expense)
    return expense


@router.get("/{expense_id}", response_model=ExpenseRead)
def get_expense(expense_id: int, session: SessionDep) -> Expense:
    return _get_or_404(session, expense_id)


@router.patch("/{expense_id}", response_model=ExpenseRead)
def update_expense(
    expense_id: int,
    payload: ExpenseUpdate,
    session: SessionDep,
) -> Expense:
    expense = _get_or_404(session, expense_id)
    for key, value in payload.model_dump(exclude_unset=True).items():
        setattr(expense, key, value)
    session.commit()
    session.refresh(expense)
    return expense


@router.delete("/{expense_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_expense(expense_id: int, session: SessionDep) -> Response:
    session.delete(_get_or_404(session, expense_id))
    session.commit()
    return Response(status_code=status.HTTP_204_NO_CONTENT)

from fastapi.testclient import TestClient

PAYLOAD = {
    "description": "Some longer description text.",
    "amount": 9.5,
    "spent_on": "2025-01-15",
}


def test_create_and_get_expense(client: TestClient) -> None:
    response = client.post("/expenses", json=PAYLOAD)
    assert response.status_code == 201, response.text
    created = response.json()
    assert created["description"] == "Some longer description text."
    assert created["amount"] == 9.5
    fetched = client.get(f"/expenses/{created['id']}")
    assert fetched.status_code == 200
    assert fetched.json()["id"] == created["id"]


def test_list_expense_supports_pagination(client: TestClient) -> None:
    for _ in range(3):
        assert client.post("/expenses", json=PAYLOAD).status_code == 201
    page = client.get("/expenses", params={"limit": 2, "offset": 1})
    assert page.status_code == 200
    assert len(page.json()) == 2


def test_update_expense(client: TestClient) -> None:
    created = client.post("/expenses", json=PAYLOAD).json()
    response = client.patch(
        f"/expenses/{created['id']}", json={"description": "Revised description text."}
    )
    assert response.status_code == 200
    assert response.json()["description"] == "Revised description text."


def test_delete_expense(client: TestClient) -> None:
    created = client.post("/expenses", json=PAYLOAD).json()
    assert client.delete(f"/expenses/{created['id']}").status_code == 204
    assert client.get(f"/expenses/{created['id']}").status_code == 404


def test_unknown_expense_returns_404(client: TestClient) -> None:
    assert client.get("/expenses/999999").status_code == 404


def test_create_expense_rejects_missing_required_fields(client: TestClient) -> None:
    assert client.post("/expenses", json={}).status_code == 422


def test_update_expense_rejects_null_required_field(client: TestClient) -> None:
    created = client.post("/expenses", json=PAYLOAD).json()
    response = client.patch(f"/expenses/{created['id']}", json={"description": None})
    assert response.status_code == 422

terraform {
  required_version = ">= 1.6"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Name prefix for every resource"
  type        = string
  default     = "expenses-service"
}

variable "image_tag" {
  description = "Immutable image tag in the ECR repository to run (e.g. a git SHA)"
  type        = string
}

variable "vpc_id" {
  description = "VPC the service runs in"
  type        = string
}

variable "subnet_ids" {
  description = "Private subnets for the Fargate tasks"
  type        = list(string)
}

variable "container_port" {
  description = "Port the container listens on"
  type        = number
  default     = 8000
}

variable "desired_count" {
  description = "Number of running tasks"
  type        = number
  default     = 2
}

variable "database_url_secret_arn" {
  description = "Optional Secrets Manager ARN holding DATABASE_URL"
  type        = string
  default     = ""
}

locals {
  secrets = var.database_url_secret_arn == "" ? [] : [
    { name = "DATABASE_URL", valueFrom = var.database_url_secret_arn }
  ]
}

resource "aws_ecr_repository" "app" {
  name                 = var.name
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }
}

resource "aws_cloudwatch_log_group" "app" {
  name              = "/ecs/${var.name}"
  retention_in_days = 30
}

resource "aws_ecs_cluster" "this" {
  name = var.name

  setting {
    name  = "containerInsights"
    value = "enabled"
  }
}

data "aws_iam_policy_document" "ecs_tasks_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "execution" {
  name               = "${var.name}-execution"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume.json
}

resource "aws_iam_role_policy_attachment" "execution" {
  role       = aws_iam_role.execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_security_group" "service" {
  name        = "${var.name}-service"
  description = "Ingress to the ${var.name} tasks"
  vpc_id      = var.vpc_id

  ingress {
    description = "HTTP from inside the VPC"
    from_port   = var.container_port
    to_port     = var.container_port
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/8"]
  }

  egress {
    description = "Outbound HTTPS and database traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_ecs_task_definition" "app" {
  family                   = var.name
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = 256
  memory                   = 512
  execution_role_arn       = aws_iam_role.execution.arn

  container_definitions = jsonencode([
    {
      name         = "api"
      image        = "${aws_ecr_repository.app.repository_url}:${var.image_tag}"
      essential    = true
      portMappings = [{ containerPort = var.container_port, protocol = "tcp" }]
      secrets      = local.secrets
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          awslogs-group         = aws_cloudwatch_log_group.app.name
          awslogs-region        = var.region
          awslogs-stream-prefix = "api"
        }
      }
    }
  ])
}

resource "aws_ecs_service" "app" {
  name            = var.name
  cluster         = aws_ecs_cluster.this.id
  task_definition = aws_ecs_task_definition.app.arn
  desired_count   = var.desired_count
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = var.subnet_ids
    security_groups  = [aws_security_group.service.id]
    assign_public_ip = false
  }

  deployment_circuit_breaker {
    enable   = true
    rollback = true
  }
}

output "ecr_repository_url" {
  description = "Push the image here"
  value       = aws_ecr_repository.app.repository_url
}

output "ecs_service_name" {
  description = "Name of the ECS service"
  value       = aws_ecs_service.app.name
}
